// The client package (packages/client) keeps two files taken from the server: the OpenAPI contract and the list of request error
// codes. They are generated by `npm run gen:client`; this test fails when a route, a schema or a code of the server changes and
// the files are not regenerated, so the client can never describe an API that is no longer there. No network, no dependency of
// the package: it builds the application in process like every other test.
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'
import { liveOpenapi, requestErrorCodes, serializeContract, serializeErrorCodes } from '../packages/client/scripts/contract.mjs'

const packageFile = (path) => readFileSync(fileURLToPath(new URL(`../packages/client/${path}`, import.meta.url)), 'utf8')
const REGENERATE = 'Run `npm run gen:client` and commit the result.'

test('packages/client/openapi.json is the contract that GET /api/openapi.json serves', async () => {
  const live = await liveOpenapi()
  const written = JSON.parse(packageFile('openapi.json'))
  const routes = (doc) => Object.entries(doc.paths).flatMap(([path, item]) => Object.keys(item).filter((m) => m !== 'parameters').map((m) => `${m.toUpperCase()} ${path}`)).sort()
  assert.deepEqual(routes(written), routes(live), `The routes of the client contract differ from the real ones. ${REGENERATE}`)
  assert.equal(packageFile('openapi.json'), serializeContract(live), `openapi.json differs from the live contract. ${REGENERATE}`)
})

test('packages/client/src/generated/error-codes.ts lists the codes the server can answer with', () => {
  assert.equal(packageFile('src/generated/error-codes.ts'), serializeErrorCodes(requestErrorCodes()), `The error codes differ from the server's. ${REGENERATE}`)
})

test('the client package declares a version of its own and exports the core and the React entry', () => {
  const pkg = JSON.parse(packageFile('package.json'))
  assert.equal(pkg.name, '@team-platform/client')
  assert.deepEqual(Object.keys(pkg.exports).sort(), ['.', './openapi.json', './package.json', './react'])
  assert.equal(pkg.dependencies, undefined, 'the client has no runtime dependencies')
  assert.equal(pkg.peerDependenciesMeta.react.optional, true, 'the core works without React')
})
